"""REFERENCE: an accepted Codeforces submission: compiles the C++ below with g++ -O2 (once, cached next to this file) and runs it on stdin."""
import hashlib
import os
import subprocess
import sys

SRC = '#include <bits/stdc++.h>\n#pragma GCC optimize(3)\nusing namespace std;\nusing ll = long long;\ntemplate <class T>\nvoid read(T &x) {\n  char ch;\n  x = 0;\n  int f = 1;\n  while (isspace(ch = getchar_unlocked()))\n    ;\n  if (ch == \'-\') ch = getchar_unlocked(), f = -1;\n  do x = x * 10 + (ch - \'0\');\n  while (isdigit(ch = getchar_unlocked()));\n  x *= f;\n}\ntemplate <class T, class... A>\nvoid read(T &x, A &...args) {\n  read(x);\n  read(args...);\n}\nconst int B = 18;\nconst int N = 100005;\nconst ll INF = 0x3f3f3f3f3f3f3f3f;\nint phi[N], p[N], pc = 0;\nbool np[N];\nvoid sieve(int n) {\n  phi[1] = 1;\n  for (int i = 2; i <= n; ++i) {\n    if (!np[i]) p[++pc] = i, phi[i] = i - 1;\n    for (int j = 1; j <= pc && i * p[j] <= n; ++j) {\n      np[i * p[j]] = true;\n      if (i % p[j] == 0) {\n        phi[i * p[j]] = phi[i] * p[j];\n        break;\n      }\n      phi[i * p[j]] = phi[i] * (p[j] - 1);\n    }\n  }\n}\nstruct node {\n  ll mn[B], tag;\n} t[N * 4];\nvoid up(int x) {\n  for (int i = 0; i < B; ++i)\n    t[x].mn[i] = min(t[x << 1].mn[i], t[x << 1 | 1].mn[i]) + t[x].tag;\n}\nvoid tag(int x, int val) {\n  for (int i = 0; i < B; ++i) t[x].mn[i] += val;\n  t[x].tag += val;\n}\nvoid modify(int x, int l, int r, int ql, int qr, int v) {\n  if (ql <= l && r <= qr) {\n    tag(x, v);\n    return;\n  }\n  int mid = (l + r) >> 1;\n  if (ql <= mid) modify(x << 1, l, mid, ql, qr, v);\n  if (qr > mid) modify(x << 1 | 1, mid + 1, r, ql, qr, v);\n  up(x);\n}\nvoid assign(int x, int l, int r, int p, const ll *v, int tag = 0) {\n  if (l == r) {\n    for (int i = 0; i < B; ++i) t[x].mn[i] = v[i] - tag;\n    return;\n  }\n  int mid = (l + r) >> 1;\n  tag += t[x].tag;\n  p <= mid ? assign(x << 1, l, mid, p, v, tag)\n           : assign(x << 1 | 1, mid + 1, r, p, v, tag);\n  up(x);\n}\nvoid build(int x, int l, int r) {\n  memset(t[x].mn, 0x3f, sizeof(t[x].mn));\n  if (l == 0) t[x].mn[0] = 0;\n  t[x].tag = 0;\n  if (l == r) return;\n  int mid = (l + r) >> 1;\n  build(x << 1, l, mid);\n  build(x << 1 | 1, mid + 1, r);\n}\nll dp[N][B];\nvector<int> di[N];\nvoid prework(int n) {\n  sieve(n);\n  for (int i = 1; i <= n; ++i)\n    for (int j = i; j <= n; j += i) di[j].push_back(i);\n  build(1, 0, n);\n  for (int i = 1; i <= n; ++i) {\n    for (int d : di[i]) modify(1, 0, n, 0, d - 1, phi[i / d]);\n    dp[i][0] = INF;\n    for (int j = 0; j < B - 1; ++j) dp[i][j + 1] = t[1].mn[j];\n    assign(1, 0, n, i, dp[i]);\n  }\n}\nint main() {\n  int qc;\n  read(qc);\n  prework(100000);\n  while (qc--) {\n    int n, k;\n    read(n, k);\n    if (k >= B)\n      printf("%d\\n", n);\n    else\n      printf("%lld\\n", dp[n][k]);\n  }\n  return 0;\n}\n'

here = os.path.dirname(os.path.abspath(__file__))
exe = os.path.join(here, ".build-" + hashlib.sha1(SRC.encode()).hexdigest()[:12])
if not os.path.exists(exe):
    with open(exe + ".cpp", "w") as f:
        f.write(SRC)
    subprocess.run(["g++", "-O2", "-std=gnu++17", "-o", exe, exe + ".cpp"], check=True)
sys.exit(subprocess.run([exe]).returncode)
